import{_ as i,l as s,o as e,c as l,v as r,p as n,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"上下文无关文法","description":"","frontmatter":{"title":"上下文无关文法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cfg-grammar.md","filePath":"cs/cfg-grammar.md","lastUpdated":1789023840000}'),h={name:"cs/cfg-grammar.md"};function m(_,a,C,f,A,E){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="上下文无关文法" tabindex="-1">上下文无关文法 <a class="header-anchor" href="#上下文无关文法" aria-label="Permalink to &quot;上下文无关文法&quot;">​</a></h1><div class="epigraph"><p>短语结构用产生式 $A\\to\\alpha$ 递归展开；推导树给出嵌套，正则做不到的括号匹配在这里落地。</p><footer>—— 据 Chomsky, On Certain Formal Properties of Grammars, 1959；龙书第 4 章整理</footer></div><p>上一课<a href="/cs/thompson-nfa">Thompson 构造</a>交出记号流。本课不重写 DFA。缺口是：表达式、语句、声明的<strong>嵌套</strong>。正则无法强制括号配对。上下文无关文法（CFG）以非终结符加产生式描述记号上的语言。本课只钉文法、推导、二义；怎么造分析器是后课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记号流是否为一份合法程序，不能只靠有限记忆。CFG：\\(G=(V,\\Sigma,P,S)\\)，\\(\\Sigma\\) 是记号种别，\\(P\\) 为 \\(A\\to\\alpha\\)。最左推导对应一种分析次序。语言 \\(L(G)\\) 是 \\(S\\) 能推出的终结串。缺口是这份定义，不是 Yacc 的语法。</p><p>二义：同一串两棵不同的推导树。悬空 else、运算符结合性必须用改写文法或后课的优先级声明消除，否则语义没有唯一 AST。</p><h3 id="cfg-不是「有上下文」" tabindex="-1">CFG 不是「有上下文」 <a class="header-anchor" href="#cfg-不是「有上下文」" aria-label="Permalink to &quot;CFG 不是「有上下文」&quot;">​</a></h3><p>名字易误导：产生式左端是单个非终结符，<strong>不看</strong>周围上下文。上下文有关文法是另一族，编译前端不用。类型规则「此处该是 int」是语义，不是 CFG 的上下文。</p><p><span class="marginnote">Chomsky 层级把正则放在 CFG 之下：每个正则语言上下文无关。龙书第 4 章用表达式文法当第一份例子。本课记号已由词法切好，\\(\\Sigma\\) 不是字符。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写表达式与语句的产生式。给出最左推导与一棵树。指出二义并改写成强制结合（\\(E\\to E+T\\mid T\\)）。ε 产生式允许可选结构。开始符号对应「编译单元」。</p>',11)),(e(),n(p,null,{default:t(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%BC%80%E5%A7%8B%E7%AC%A6%E5%8F%B7%22%5D%20--%3E%20P%5B%22%E4%BA%A7%E7%94%9F%E5%BC%8F%E5%B1%95%E5%BC%80%22%5D%0A%20%20P%20--%3E%20T%5B%22%E6%8E%A8%E5%AF%BC%E6%A0%91%22%5D%0A%20%20T%20--%3E%20AMB%5B%22%E6%98%AF%E5%90%A6%E4%BA%8C%E4%B9%89%EF%BC%9F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p><a href="/cs/tree-as-acyclic">树</a>已定义；推导树是有序树，叶为记号。后课 AST 丢掉纯语法糖节点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CFG 的分析问题：给定 \\(G\\) 与记号串，是否 \\(w\\in L(G)\\) 并可建树。一般 CFG 可用 CYK 等动态规划，多项式但慢；程序语言用受限族（LL、LR）线性。本课不写 CYK。左递归对后课递归下降有害，点名留给那一课消除。</p><p>正则词法仍负责标识符拼写；CFG 只看见 <code>id</code> 种别。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写递归下降代码，不算 FIRST/FOLLOW，不移进归约。语义动作不进产生式（那是语法制导，AST 课才挂）。也不用 CFG 描述空白——空白已在词法消失。</p><p>后课默认：程序结构是某份（希望无二义的）CFG。递归下降是下一课把最左推导写成函数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CFG 用单非终结符产生式描述嵌套；推导树是结构。</li><li>二义必须消；正则只管词法。</li><li>分析算法分家：本课只给语言。</li><li>出处：Chomsky, 1959；Aho et al., 龙书第 4 章。</li></ul>',9))])}const F=i(h,[["render",m]]);export{T as __pageData,F as default};
